import{_ as i,o as a,c as n,ai as e}from"./chunks/framework.Ai2o9gNv.js";const l="/assets/image-20241124191141178.fEIK_Kfe.png",p="/assets/image-20241124191156792.CbSK8FZz.png",t="/assets/image-20241124191241104.IQAUpNV6.png",h="/assets/image-20241124191300505.CSyse3xt.png",r="/assets/image-20241124191643071.Ci7LEgrm.png",k="/assets/image-20241124191744693.BBoTzSSW.png",E="/assets/image-20241124191327227.BWJ6xVnJ.png",c="/assets/image-20241124191343134.BGNv5Uz3.png",o="/assets/PixPin_2024-11-24_19-15-16.CyY0klIC.gif",d="/assets/image-20241124191814129.DNBl_n2X.png",g="/assets/image-20241124192132959.D-zWMOTI.png",m="/assets/image-20241124192208171.CSfREwLW.png",b="/assets/image-20241124192221915.BG1l1ZYB.png",y="/assets/image-20241124192250939.Wl4xXo8E.png",u="/assets/image-20241124192911325.B_M7aieP.png",F="/assets/PixPin_2024-11-24_19-32-52.U4dYihBv.gif",C="/assets/image-20241124193502932.CjSwzxmc.png",B="/assets/image-20241124193524156.BKPoBNeB.png",A="/assets/PixPin_2024-11-24_19-40-02.5rxDh-8h.gif",v="/assets/image-20241124194101296.B0tV0ENC.png",D="/assets/image-20241124194121169.C58-KDA6.png",S="/assets/image-20241124194443319.B7jVPb1K.png",_="/assets/image-20241124194529204.Dov-uo65.png",x="/assets/image-20241124194617678.DYPClB42.png",T=JSON.parse(`{"title":"元服务","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS Next 简单上手元服务开发/HarmonyOS Next 简单上手元服务开发.md","filePath":"鸿蒙开发技巧/HarmonyOS Next 简单上手元服务开发/HarmonyOS Next 简单上手元服务开发.md","lastUpdated":1772610595000,"__rawMarkdown":"# 元服务\\n\\n万物互联时代，人均持有设备量不断攀升，设备种类和使用场景更加多样，使得应用开发、应用入口变得更加复杂。在此背景下，应用提\\n\\n供方和用户迫切需要一种新的服务提供方式，使应用开发更简单、服务（如听音乐、打车等）的获取和使用更便捷。为此，HarmonyOS\\n\\n除支持传统的需要安装的应用（以下简称传统应用）外，还支持更加方便快捷的免安装的应用，即元服务。\\n\\n元服务是 HarmonyOS 提供的一种轻量应用程序形态，具备秒开直达，纯净清爽；服务相伴，恰合时宜；即用即走，账号相随；一体两\\n\\n面，嵌入运行；原生智能，全域搜索；高效开发，生而可信等特征。\\n\\n元服务可独立上架、分发、运行，独立实现业务闭环，可大幅提升信息与服务的获取效率。\\n\\n# 元服务和应用的的区别\\n\\n![image-20241124191141178](HarmonyOS%20Next%20%E7%AE%80%E5%8D%95%E4%B8%8A%E6%89%8B%E5%85%83%E6%9C%8D%E5%8A%A1%E5%BC%80%E5%8F%91.assets/image-20241124191141178.png)\\n\\n# 元服务开发旅程\\n\\n![image-20241124191156792](HarmonyOS%20Next%20%E7%AE%80%E5%8D%95%E4%B8%8A%E6%89%8B%E5%85%83%E6%9C%8D%E5%8A%A1%E5%BC%80%E5%8F%91.assets/image-20241124191156792.png)\\n\\n# 在 AGC 平台上新建一个项目\\n\\n[链接](https://developer.huawei.com/consumer/cn/service/josp/agc/index.html#/harmonyOSDevPlatform/172249065903274453)\\n\\n一个项目可以多个应用\\n\\n![image-20241124191241104](HarmonyOS%20Next%20%E7%AE%80%E5%8D%95%E4%B8%8A%E6%89%8B%E5%85%83%E6%9C%8D%E5%8A%A1%E5%BC%80%E5%8F%91.assets/image-20241124191241104.png)\\n\\n# AGC 新建一个元服务应用\\n\\n![image-20241124191300505](HarmonyOS%20Next%20%E7%AE%80%E5%8D%95%E4%B8%8A%E6%89%8B%E5%85%83%E6%9C%8D%E5%8A%A1%E5%BC%80%E5%8F%91.assets/image-20241124191300505.png)\\n\\n# 新建一个本地元服务项目\\n\\n![image-20241124191643071](HarmonyOS%20Next%20%E7%AE%80%E5%8D%95%E4%B8%8A%E6%89%8B%E5%85%83%E6%9C%8D%E5%8A%A1%E5%BC%80%E5%8F%91.assets/image-20241124191643071.png)\\n\\n---\\n\\n如果成功在 AGC 平台上新建过元服务，那么这里会自动显示\\n\\n![image-20241124191744693](HarmonyOS%20Next%20%E7%AE%80%E5%8D%95%E4%B8%8A%E6%89%8B%E5%85%83%E6%9C%8D%E5%8A%A1%E5%BC%80%E5%8F%91.assets/image-20241124191744693.png)\\n\\n# 修改元服务名称\\n\\n![image-20241124191327227](HarmonyOS%20Next%20%E7%AE%80%E5%8D%95%E4%B8%8A%E6%89%8B%E5%85%83%E6%9C%8D%E5%8A%A1%E5%BC%80%E5%8F%91.assets/image-20241124191327227.png)\\n\\n# 修改元服务图标\\n\\n重要，上架审核很严谨\\n\\n![image-20241124191343134](HarmonyOS%20Next%20%E7%AE%80%E5%8D%95%E4%B8%8A%E6%89%8B%E5%85%83%E6%9C%8D%E5%8A%A1%E5%BC%80%E5%8F%91.assets/image-20241124191343134.png)\\n\\n1. 先自己下载随意一张图片\\n\\n2. 使用画图工具 图像属性 修改 1024px\\n\\n   ![PixPin_2024-11-24_19-15-16](HarmonyOS%20Next%20%E7%AE%80%E5%8D%95%E4%B8%8A%E6%89%8B%E5%85%83%E6%9C%8D%E5%8A%A1%E5%BC%80%E5%8F%91.assets/PixPin_2024-11-24_19-15-16.gif)\\n\\n3. 使用开发工具中 Image Asset 来制作图片\\n\\n![image-20241124191814129](HarmonyOS%20Next%20%E7%AE%80%E5%8D%95%E4%B8%8A%E6%89%8B%E5%85%83%E6%9C%8D%E5%8A%A1%E5%BC%80%E5%8F%91.assets/image-20241124191814129.png)\\n\\n![image-20241124192132959](HarmonyOS%20Next%20%E7%AE%80%E5%8D%95%E4%B8%8A%E6%89%8B%E5%85%83%E6%9C%8D%E5%8A%A1%E5%BC%80%E5%8F%91.assets/image-20241124192132959.png)\\n\\n# 新增元服务卡片\\n\\n> Win 模拟器 不支持新增元服务的卡片\\n\\n## 新建卡片\\n\\n![image-20241124192208171](HarmonyOS%20Next%20%E7%AE%80%E5%8D%95%E4%B8%8A%E6%89%8B%E5%85%83%E6%9C%8D%E5%8A%A1%E5%BC%80%E5%8F%91.assets/image-20241124192208171.png)\\n\\n![image-20241124192221915](HarmonyOS%20Next%20%E7%AE%80%E5%8D%95%E4%B8%8A%E6%89%8B%E5%85%83%E6%9C%8D%E5%8A%A1%E5%BC%80%E5%8F%91.assets/image-20241124192221915.png)\\n\\n# 元服务开发中收到的限制\\n\\n## 每一个包大小不能超过 2M\\n\\n![image-20241124192250939](HarmonyOS%20Next%20%E7%AE%80%E5%8D%95%E4%B8%8A%E6%89%8B%E5%85%83%E6%9C%8D%E5%8A%A1%E5%BC%80%E5%8F%91.assets/image-20241124192250939.png)\\n\\n## 元服务项目总大小 一般是 10M，特殊情况可以申请 20M\\n\\n## 服务卡片最多 16 张\\n\\n## 服务卡片不能随意通过卡片跳转其他其他应用或者元服务\\n\\n## 服务卡片不能使用 call 事件\\n\\n# AtomicServiceTabs\\n\\n[实现 tab 切换和标题设置](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/ohos-atomicservice-atomicservicetabs-V5#%E7%A4%BA%E4%BE%8B)\\n\\n![image-20241124192911325](HarmonyOS%20Next%20%E7%AE%80%E5%8D%95%E4%B8%8A%E6%89%8B%E5%85%83%E6%9C%8D%E5%8A%A1%E5%BC%80%E5%8F%91.assets/image-20241124192911325.png)\\n\\n\`\`\`typescript\\n// Index.ets\\nimport { AtomicServiceTabs, TabBarOptions, TabBarPosition, OnContentWillChangeCallback } from '@kit.ArkUI';\\n\\n@Entry\\n@Component\\nstruct Index {\\n  @State message: string = '首页';\\n  @State currentIndex: number = 0;\\n\\n  @Builder\\n  tabContent1() {\\n    Column().width('100%').height('100%').alignItems(HorizontalAlign.Center).backgroundColor('#00CB87')\\n  }\\n\\n  @Builder\\n  tabContent2() {\\n    Column().width('100%').height('100%').backgroundColor('#007DFF')\\n  }\\n\\n  @Builder\\n  tabContent3() {\\n    Column().width('100%').height('100%').backgroundColor('#FFBF00')\\n  }\\n\\n  build() {\\n    Stack() {\\n      AtomicServiceTabs({\\n        tabContents: [\\n          () => {\\n            this.tabContent1()\\n          },\\n          () => {\\n            this.tabContent2()\\n          },\\n          () => {\\n            this.tabContent3()\\n          }\\n        ],\\n        tabBarOptionsArray: [\\n          new TabBarOptions($r('sys.media.ohos_ic_public_phone'), '绿色', Color.Black, Color.Blue),\\n          new TabBarOptions($r('sys.media.ohos_ic_public_location'), '蓝色', Color.Black, Color.Blue),\\n          new TabBarOptions($r('sys.media.ohos_ic_public_more'), '黄色', Color.Black, Color.Blue)\\n        ],\\n        tabBarPosition: TabBarPosition.BOTTOM,\\n        barBackgroundColor: $r('sys.color.ohos_id_color_bottom_tab_bg'),\\n\\n      })\\n\\n    }.height('100%')\\n  }\\n}\\n\`\`\`\\n\\n# AtomicServiceNavigation\\n\\n[路由管理](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/ohos-atomicservice-atomicservicenavigation-V5#%E7%A4%BA%E4%BE%8B)\\n\\n![PixPin_2024-11-24_19-32-52](HarmonyOS%20Next%20%E7%AE%80%E5%8D%95%E4%B8%8A%E6%89%8B%E5%85%83%E6%9C%8D%E5%8A%A1%E5%BC%80%E5%8F%91.assets/PixPin_2024-11-24_19-32-52.gif)\\n\\n## Index\\n\\n\`\`\`typescript\\n// Index.ets\\nimport {\\n  AtomicServiceNavigation,\\n  NavDestinationBuilder,\\n  AtomicServiceTabs,\\n  TabBarOptions,\\n  TabBarPosition\\n} from '@kit.ArkUI';\\nimport { HomeView } from '../views/HomeView';\\n\\nexport interface IParam {\\n  id: number\\n}\\n\\n@Entry\\n@Component\\nstruct Index {\\n  @StorageProp(\\"safeTop\\")\\n  safeTop: number = 0\\n  @StorageProp(\\"safeBottom\\")\\n  safeBottom: number = 0\\n  @State message: string = '主题';\\n  // 页面跳转\\n  @Provide(\\"pathStack\\")\\n  pathStack: NavPathStack = new NavPathStack();\\n\\n  @Builder\\n  navigationContent() {\\n    Button(\\"内容\\")\\n      .onClick(() => {\\n        const param: IParam = { id: 100 }\\n        this.pathStack.pushPathByName(\\"HomeView\\", param)\\n      })\\n  }\\n\\n  @Builder\\n  // 路由页面映射的  以前 navNavigation 修改配置文件！！！\\n  pageMap(name: string) {\\n    if (name === 'HomeView') {\\n      HomeView()\\n    }\\n  }\\n\\n  build() {\\n    Row() {\\n      Column() {\\n        // navNavigation 类似\\n        AtomicServiceNavigation({\\n          // 容器内直接显示的内容\\n          navigationContent: () => {\\n            this.navigationContent()\\n          },\\n          // 标题！！\\n          title: this.message,\\n          //\\n          titleOptions: {\\n            backgroundColor: '#fff',\\n            isBlurEnabled: false\\n          },\\n          // 路由页面映射\\n          navDestinationBuilder: this.pageMap,\\n          navPathStack: this.pathStack,\\n          mode: NavigationMode.Stack\\n        })\\n      }\\n      .width('100%')\\n    }\\n    .height('100%')\\n    .padding({\\n      top: this.safeTop,\\n      bottom: this.safeBottom\\n    })\\n  }\\n}\\n\\n\`\`\`\\n\\n## HomeView\\n\\n\`\`\`typescript\\nimport { IParam } from \\"../pages/Index\\"\\nimport { promptAction } from \\"@kit.ArkUI\\"\\n\\n@Component\\nexport struct HomeView {\\n  @Consume(\\"pathStack\\")\\n  pathStack: NavPathStack\\n\\n  aboutToAppear() {\\n    const param = this.pathStack.getParamByName(\\"HomeView\\").pop() as IParam\\n    promptAction.showToast({ message: \`\${param.id}\` })\\n  }\\n\\n  build() {\\n    NavDestination() {\\n      Column() {\\n        Text(\\"homeView\\")\\n          .fontSize(50)\\n      }\\n      .width(\\"100%\\")\\n      .height(\\"100%\\")\\n      .justifyContent(FlexAlign.Center)\\n    }\\n  }\\n}\\n\`\`\`\\n\\n# AtomicServiceWeb\\n\\n为开发者提供满足定制化诉求的 Web 高阶组件，屏蔽原生 Web 组件中无需关注的接口，并提供 JS 扩展能力\\n\\nAtomicServiceWeb 后续将不再支持[registerJavaScriptProxy](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V13/js-apis-webview-V13#registerjavascriptproxy)、[runJavaScript](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V13/js-apis-webview-V13#runjavascript-1)等接口。若需要 Web 组件加载的网页中调用元服务原生页面\\n\\n的对象方法，可通过 JS SDK 提供的接口获取相关数据。若 JS SDK 接口无法满足需求，还可通过传参的方式，元服务原生页面执行对象方法\\n\\n后获取结果，将结果传递给 Web 组件加载的网页中。\\n\\n在元服务内，仅能使用 AtomicServiceWeb 组件显示 Web 页面，且需要配置业务域名。\\n\\n请参考：[AtomicServiceWeb 组件参考](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/ohos-atomicservice-atomicserviceweb-V5)、[配置业务域名](https://developer.huawei.com/consumer/cn/doc/atomic-guides-V5/agc-help-harmonyos-business-domain-V5)\\n\\n## 基本使用\\n\\n1. 新建了组件**WebHome** 用来显示 **AtomicServiceWeb**容器\\n\\n   1. \`\`\`JavaScript\\n      import { AtomicServiceWeb, AtomicServiceWebController } from '@ohos.atomicservice.AtomicServiceWeb'\\n\\n      @Entry\\n      @Component\\n      export struct WebHome {\\n        @State\\n        ascontroller: AtomicServiceWebController = new AtomicServiceWebController()\\n\\n        build() {\\n          NavDestination() {\\n            Column() {\\n              AtomicServiceWeb({ src: $rawfile(\\"index.html\\"), controller: this.ascontroller })\\n                .width(\\"100%\\")\\n                .height(\\"100%\\")\\n            }\\n            .width(\\"100%\\")\\n            .height(\\"100%\\")\\n            .justifyContent(FlexAlign.Center)\\n          }\\n        }\\n      }\\n      \`\`\`\\n\\n2. 新建 h5 页面 index.html\\n\\n   ![image-20241124193502932](HarmonyOS%20Next%20%E7%AE%80%E5%8D%95%E4%B8%8A%E6%89%8B%E5%85%83%E6%9C%8D%E5%8A%A1%E5%BC%80%E5%8F%91.assets/image-20241124193502932.png)\\n\\n   \`\`\`html\\n   <!DOCTYPE html>\\n   <html lang=\\"en\\">\\n     <head>\\n       <meta charset=\\"UTF-8\\" />\\n       <meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1.0\\" />\\n       <title>Document</title>\\n       <style>\\n         body {\\n           background-color: red;\\n         }\\n       </style>\\n     </head>\\n     <body></body>\\n   </html>\\n   \`\`\`\\n\\n3. 在 Index 添加了添加跳转到 WebHome\\n\\n   ![image-20241124193524156](HarmonyOS%20Next%20%E7%AE%80%E5%8D%95%E4%B8%8A%E6%89%8B%E5%85%83%E6%9C%8D%E5%8A%A1%E5%BC%80%E5%8F%91.assets/image-20241124193524156.png)\\n\\n4. WebHome 使用 **AtomicServiceWeb 容器显示内容**\\n\\n   ![PixPin_2024-11-24_19-40-02](HarmonyOS%20Next%20%E7%AE%80%E5%8D%95%E4%B8%8A%E6%89%8B%E5%85%83%E6%9C%8D%E5%8A%A1%E5%BC%80%E5%8F%91.assets/PixPin_2024-11-24_19-40-02.gif)\\n\\n## 鸿蒙页面传递数据到 h5 页面\\n\\n通过 src 属性传递\\n\\n![image-20241124194101296](HarmonyOS%20Next%20%E7%AE%80%E5%8D%95%E4%B8%8A%E6%89%8B%E5%85%83%E6%9C%8D%E5%8A%A1%E5%BC%80%E5%8F%91.assets/image-20241124194101296.png)\\n\\n### h5 页面接收和处理\\n\\n![image-20241124194121169](HarmonyOS%20Next%20%E7%AE%80%E5%8D%95%E4%B8%8A%E6%89%8B%E5%85%83%E6%9C%8D%E5%8A%A1%E5%BC%80%E5%8F%91.assets/image-20241124194121169.png)\\n\\n## h5 页面调用元服务方法\\n\\nhtml 中，如果需要调用元服务 API，可集成元服务 JS SDK，调用相关 API 进行访问\\n\\n**安装**\\n\\n\`\`\`\\nnpm install @atomicservice/asweb-sdk\\n\`\`\`\\n\\n## 使用方法\\n\\n### es6\\n\\n\`\`\`typescript\\nimport has from \\"@atomicservice/asweb-sdk\\";\\nhas.asWeb.getEnv({ callback: (err, res) => {} });\\n\`\`\`\\n\\n### umd\\n\\n\`\`\`xml\\n&lt;script src=\\"../dist/asweb-sdk.umd.js\\"&gt;&lt;/script&gt;\\n&lt;script&gt;\\n  has.asWeb.getEnv({\\n    callback: (err, res) => {\\n    }\\n  });\\n&lt;/script&gt;\\n\`\`\`\\n\\n### 更多方法\\n\\n![image-20241124194443319](HarmonyOS%20Next%20%E7%AE%80%E5%8D%95%E4%B8%8A%E6%89%8B%E5%85%83%E6%9C%8D%E5%8A%A1%E5%BC%80%E5%8F%91.assets/image-20241124194443319.png)\\n\\n# 元服务发送网络请求\\n\\n1. 申请权限 在 AGC 平台上 把请求的域名填写到 白名单中 - **上线必须要做**\\n\\n   ![image-20241124194529204](HarmonyOS%20Next%20%E7%AE%80%E5%8D%95%E4%B8%8A%E6%89%8B%E5%85%83%E6%9C%8D%E5%8A%A1%E5%BC%80%E5%8F%91.assets/image-20241124194529204.png)\\n\\n2. 在手机-设置-系统-应用-元服务豁免管控 **打开** - 开发阶段也能发送请求\\n\\n   > 模拟器不受限制\\n\\n## 总结\\n\\n![image-20241124194617678](HarmonyOS%20Next%20%E7%AE%80%E5%8D%95%E4%B8%8A%E6%89%8B%E5%85%83%E6%9C%8D%E5%8A%A1%E5%BC%80%E5%8F%91.assets/image-20241124194617678.png)\\n\\n---\\n\\n我的博客即将同步至腾讯云开发者社区，邀请大家一同入驻：https://cloud.tencent.com/developer/support-plan?invite_code=huv4f5rpu4g\\n"}`),f={name:"鸿蒙开发技巧/HarmonyOS Next 简单上手元服务开发/HarmonyOS Next 简单上手元服务开发.md"};function q(P,s,w,N,H,O){return a(),n("div",null,[...s[0]||(s[0]=[e("",84)])])}const V=i(f,[["render",q]]);export{T as __pageData,V as default};
